<script setup lang="ts">
import {commandErrorStatus} from '@/composables/aippt/commandError'

import { ref,computed,watch,onBeforeUnmount,nextTick } from 'vue'
import { api,download } from '@/api/aippt'
import { waitTask } from '@/composables/aippt/useTaskResult'
import {resolveQualityReport} from '@/composables/aippt/qualityReport'
import type { Issue,Task } from '@/types/aippt'
const props=defineProps<{modelValue:boolean;projectId:string;title:string;deckRevision:number;themeRevision:number;flush:()=>Promise<void>}>(),emit=defineEmits<{ 'update:modelValue':[v:boolean];locate:[issue:Issue]}>();const issues=ref<Issue[]>([]),busy=ref(false),error=ref(''),acknowledged=ref(false),allowed=ref(false),snapshot=ref<{deck:number;theme:number}|null>(null),exported=ref<(Task&{asset_id?:string;download_url?:string;verify?:unknown})|null>(null);let controller:AbortController|null=null,generation=0,command:{key:string;body:Record<string,unknown>}|null=null
const blocked=computed(()=>issues.value.some(i=>i.severity==='error')),warnings=computed(()=>issues.value.some(i=>i.severity==='warning')),stale=computed(()=>snapshot.value&&(snapshot.value.deck!==props.deckRevision||snapshot.value.theme!==props.themeRevision))
async function check(){controller?.abort();const local=new AbortController();controller=local;const own=++generation,pid=props.projectId;busy.value=true;error.value='';acknowledged.value=false;snapshot.value=null;issues.value=[];allowed.value=false;try{await props.flush();await nextTick();if(own!==generation)return;const versions={deck:props.deckRevision,theme:props.themeRevision},result=await resolveQualityReport(()=>api.quality(pid),local.signal);if(own!==generation||pid!==props.projectId)return;issues.value=result.issues||[];allowed.value=(result.can_export??result.export_allowed)===true;snapshot.value=versions}catch(e:any){if(own===generation&&e.name!=='AbortError'&&e.code!=='ERR_CANCELED')error.value=e.message}finally{if(own===generation)busy.value=false}}
async function create(){if(!snapshot.value||!allowed.value||blocked.value||warnings.value&&!acknowledged.value||busy.value||error.value)return;controller?.abort();const local=new AbortController();controller=local;const own=++generation,pid=props.projectId;busy.value=true;error.value='';try{await props.flush();await nextTick();if(own!==generation)return;if(stale.value){await check();return}const body={deck_revision:props.deckRevision,theme_revision:props.themeRevision,acknowledge_warnings:acknowledged.value};if(!command||JSON.stringify(command.body)!==JSON.stringify(body))command={key:crypto.randomUUID(),body};const accepted=await api.export(pid,command.body,command.key);if(own!==generation)return;exported.value=accepted;const eid=accepted.id;if(!eid)throw new Error('后台未返回导出文件标识');await waitTask(accepted,local.signal);if(own!==generation||pid!==props.projectId||local.signal.aborted)return;const result=await api.exportState(pid,eid);if(own!==generation||pid!==props.projectId)return;exported.value=result;if(result.status!=='ready'&&result.status!=='completed')throw new Error(result.message||'文件回读未通过，暂不可下载')}catch(e:any){if(own===generation){if(commandErrorStatus(e)===409)command=null;if(e.name!=='AbortError'&&e.code!=='ERR_CANCELED')error.value=e.message}}finally{if(own===generation)busy.value=false}}
async function save(){if(!exported.value?.id)return;try{await download(exported.value.download_url||`/exports/${exported.value.id}/download`,props.title+'.pptx')}catch(e:any){error.value=e.message}}
watch(()=>[props.modelValue,props.projectId],([open],previous)=>{if(previous&&previous[1]!==props.projectId){exported.value=null;command=null}if(open)void check();else{controller?.abort();generation++;busy.value=false;snapshot.value=null;allowed.value=false}},{immediate:true});onBeforeUnmount(()=>{generation++;controller?.abort()})
</script>
<template><el-drawer :model-value="modelValue" title="质量检查与 PPTX 导出" size="min(680px,95vw)" @close="emit('update:modelValue',false)"><p>检查版本：正文{{snapshot?.deck??'—'}} / 主题{{snapshot?.theme??'—'}}。错误需要修复；警告可确认后继续。</p><el-alert v-if="error" type="error" :title="error"/><el-alert v-if="stale" title="页面或主题已变化，请重新检查当前版本。已有文件仍为原导出快照。" type="warning" :closable="false"/><el-alert v-if="!busy&&snapshot&&!allowed&&!error" title="当前版本暂不允许导出，请处理质量提示后重新检查。" type="warning" :closable="false"/><el-button :loading="busy" @click="check">重新检查</el-button><el-empty v-if="!busy&&!!snapshot&&allowed&&!issues.length&&!error" description="未发现质量问题"/><article v-for="(issue,i) in issues" :key="i" :class="['issue',issue.severity]"><el-tag :type="issue.severity==='error'?'danger':issue.severity==='warning'?'warning':'info'">{{issue.severity==='error'?'错误':issue.severity==='warning'?'警告':'提示'}}</el-tag><p>{{issue.message}}</p><el-button v-if="issue.slide_id" link type="primary" @click="emit('locate',issue)">定位到页面 / 内容块</el-button></article><el-checkbox v-if="warnings" v-model="acknowledged">已了解警告，按当前快照继续导出</el-checkbox><div class="export-actions"><el-button v-hasPermi="['aippt:export:create']" type="primary" :disabled="busy||blocked||!!stale||!snapshot||!allowed||!!error||warnings&&!acknowledged" @click="create">生成原生可编辑 PPTX</el-button><el-button v-hasPermi="['aippt:export:download']" :disabled="busy||!exported||!['ready','completed'].includes(exported.status)" @click="save">下载验证后的文件</el-button></div><div v-if="exported"><h4>导出回读结果</h4><pre>{{JSON.stringify(exported.verify||exported.result||{status:exported.status},null,2)}}</pre><p>下载文件来自导出时的不可变快照；后续编辑需再次导出。</p></div></el-drawer></template>
<style scoped>.issue{padding:16px 0;border-bottom:1px solid #ebeef5}.issue p{line-height:1.5}.export-actions{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.export-actions .el-button{margin:0}pre{white-space:pre-wrap;word-break:break-word;background:#f5f7fa;padding:14px}</style>


